 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    best_color, best_size = 0, 0
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
